package com.clara.memory.semantic.local;
import com.clara.kernel.exception.ClaraException;
import com.clara.kernel.exception.ErrorCategory;
import com.clara.kernel.exception.ErrorCodes;
import com.clara.memory.semantic.api.*;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import java.io.*;import java.nio.Buffer;import java.nio.ByteBuffer;import java.nio.channels.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
/**
 * 在本地维护语义记忆向量，使用 WAL、周期快照和独占文件锁提供进程内持久化检索。
 *
 * <p>常规用法：使用包含工作区、向量维度和容量策略的 {@link SemanticMemoryStoreConfig} 构造实例，
 * 通过 {@link #upsert} 写入，通过 {@link #search} 检索，按会话删除后在退出前调用 {@link #close()}。
 *
 * <p>注意：同一工作区一次只能打开一个实例，查询向量维度必须与配置一致。检索会强制应用租户及可选用户、
 * 会话、领域和元数据过滤；容量淘汰和过期清理由存储执行，禁止手工修改快照或 WAL。
 */
public final class LocalSemanticMemoryStore implements SemanticMemoryStore {
 private static final int FORMAT=1,MAGIC=0x434d454d;private final SemanticMemoryStoreConfig config;private final Path directory,walDirectory;private final Map<String,MemoryEntry> entries=new ConcurrentHashMap<String,MemoryEntry>();private final ObjectMapper json=new ObjectMapper();private final FileChannel lockChannel;private final FileLock lock;private long sequence,snapshotSequence;private int operations;private boolean closed;
 public LocalSemanticMemoryStore(SemanticMemoryStoreConfig config){if(config==null) {throw new IllegalArgumentException(); }this.config=config;FileChannel channel=null;FileLock acquired=null;try{Path root=config.getWorkspace().toRealPath();directory=root.resolve(".clara").resolve("memory");walDirectory=directory.resolve("wal");Files.createDirectories(walDirectory);channel=FileChannel.open(directory.resolve("lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);acquired=channel.tryLock();if(acquired==null) {throw locked(); }lockChannel=channel;lock=acquired;load();}catch(OverlappingFileLockException e){close(channel);throw locked();}catch(
         ClaraException e){close(channel);throw e;}catch(IOException e){close(channel);throw corrupted();}}
 public synchronized void upsert(List<MemoryEntry> values){open();if(values==null||values.isEmpty()||values.contains(null)) {throw new IllegalArgumentException("entries are required"); }Set<String> ids=new HashSet<String>();for(MemoryEntry entry:values){validate(entry);if(!ids.add(entry.getId())) {throw new IllegalArgumentException("duplicate memory id"); }}purgeExpired(System.currentTimeMillis());int additions=0;for(MemoryEntry entry:values)if(!entries.containsKey(entry.getId()))additions++;makeCapacity(additions,ids);append((byte)1,values,Collections.<String>emptyList());for(MemoryEntry entry:values)entries.put(entry.getId(),entry);checkpointIfNeeded();}
 public synchronized List<MemoryMatch> search(SemanticMemoryQuery query){open();if(query==null) {throw new IllegalArgumentException(); }if(query.getVector().length!=config.getDimension())mismatch();List<MemoryMatch> matches=new ArrayList<MemoryMatch>();for(MemoryEntry entry:entries.values()){if(entry.isExpired(query.getNowEpochMillis())||!entry.getTenantId().equals(query.getTenantId())||query.getUserId()!=null&&!query.getUserId().equals(entry.getUserId())||query.getConversationId()!=null&&!query.getConversationId().equals(entry.getConversationId())||query.getDomain()!=null&&!query.getDomain().equals(entry.getDomain())||!entry.getMetadata().entrySet().containsAll(query.getMetadataFilters().entrySet()))continue;double score=cosine(query.getVector(),entry.getVector());if(score>=query.getMinScore())matches.add(new MemoryMatch(entry,score));}Collections.sort(matches,new Comparator<MemoryMatch>(){public int compare(MemoryMatch a,MemoryMatch b){int score=Double.compare(b.getScore(),a.getScore());if(score!=0)return score;int time=Long.compare(b.getEntry().getCreatedAtEpochMillis(),a.getEntry().getCreatedAtEpochMillis());return time!=0?time:a.getEntry().getId().compareTo(b.getEntry().getId());}});if(matches.size()>query.getTopK())matches=new ArrayList<MemoryMatch>(matches.subList(0,query.getTopK()));return Collections.unmodifiableList(matches);}
 public synchronized void deleteByConversation(String tenant,String conversation){open();if(blank(tenant)||blank(conversation)) {throw new IllegalArgumentException(); }List<String> ids=new ArrayList<String>();for(MemoryEntry entry:entries.values())if(tenant.equals(entry.getTenantId())&&conversation.equals(entry.getConversationId()))ids.add(entry.getId());delete(ids);}
 public synchronized void close()throws IOException{if(closed)return;try{if(operations>0)snapshot();}finally{closed=true;try{lock.release();}finally{lockChannel.close();}}}
 private void load()throws IOException{Path manifest=directory.resolve("manifest.json");if(Files.exists(manifest)){Map<String,Object> value=json.readValue(Files.readAllBytes(manifest),new TypeReference<Map<String,Object>>(){});if(number(value.get("formatVersion"))!=FORMAT||!config.getWorkspaceId().equals(value.get("workspaceId"))||!config.getEmbeddingModel().equals(value.get("embeddingModel"))||!config.getEmbeddingRevision().equals(value.get("embeddingRevision"))||number(value.get("dimension"))!=config.getDimension()||!"COSINE".equals(value.get("distanceType")))mismatch();snapshotSequence=longNumber(value.get("snapshotSequence"));String snapshotName=text(value.get("snapshotFile"),"snapshot.bin"),checksumName=text(value.get("checksumFile"),"snapshot.sha256");Path snapshot=safeManaged(snapshotName),checksum=safeManaged(checksumName);if(!Files.isRegularFile(snapshot)||!Files.isRegularFile(checksum)) {throw corrupted(); }byte[] bytes=Files.readAllBytes(snapshot);String expected=new String(Files.readAllBytes(checksum),StandardCharsets.US_ASCII).trim();if(!sha(bytes).equals(expected)) {throw corrupted(); }decodeSnapshot(bytes);if(sequence!=snapshotSequence) {throw corrupted(); }}else if(Files.exists(directory.resolve("snapshot.bin"))||Files.exists(directory.resolve("snapshot.sha256"))) {throw corrupted(); }sequence=snapshotSequence;replayWal();}
 private void replayWal()throws IOException{List<Path> files=new ArrayList<Path>();DirectoryStream<Path> stream=Files.newDirectoryStream(walDirectory,"*.wal");try{for(Path file:stream)files.add(file);}finally{stream.close();}Collections.sort(files);for(int i=0;i<files.size();i++){byte[] bytes=Files.readAllBytes(files.get(i));if(bytes.length<36){if(i==files.size()-1){Files.delete(files.get(i));break;}throw corrupted();}ByteBuffer frame=ByteBuffer.wrap(bytes);int length=frame.getInt();if(length<0||bytes.length!=4+length+32){if(i==files.size()-1&&bytes.length<4+Math.max(0,length)+32){Files.delete(files.get(i));break;}throw corrupted();}byte[] payload=new byte[length],digest=new byte[32];frame.get(payload);frame.get(digest);if(!Arrays.equals(rawSha(payload),digest)) {throw corrupted(); }WalRecord record=decodeWal(payload);if(record.sequence!=sequence+1) {throw corrupted(); }apply(record);sequence=record.sequence;operations++;}}
 private void append(byte type,List<MemoryEntry> values,List<String> ids){try{long next=sequence+1;byte[] payload=encodeWal(next,type,values,ids),digest=rawSha(payload);ByteBuffer frame=ByteBuffer.allocate(4+payload.length+digest.length);frame.putInt(payload.length).put(payload).put(digest);((Buffer)frame).flip();Path target=walDirectory.resolve(String.format("%020d.wal",next)),temp=target.resolveSibling(target.getFileName()+".tmp");FileChannel channel=FileChannel.open(temp,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE);try{while(frame.hasRemaining())channel.write(frame);if(config.getDurability()==SemanticMemoryDurability.FSYNC_EACH)channel.force(true);}finally{channel.close();}Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE);sequence=next;operations++;}catch(IOException e){throw corrupted();}}
 private void checkpointIfNeeded(){if(operations>=config.getSnapshotAfterOperations())try{snapshot();}catch(IOException e){throw corrupted();}}
 private void snapshot()throws IOException{byte[] bytes=encodeSnapshot();String suffix=String.format("%020d",sequence),snapshotName="snapshot-"+suffix+".bin",checksumName="snapshot-"+suffix+".sha256";Path snapshot=directory.resolve(snapshotName),checksum=directory.resolve(checksumName),manifest=directory.resolve("manifest.json");writeAtomic(snapshot,bytes);writeAtomic(checksum,(sha(bytes)+"\n").getBytes(StandardCharsets.US_ASCII));Map<String,Object> value=new LinkedHashMap<String,Object>();value.put("formatVersion",Integer.valueOf(FORMAT));value.put("workspaceId",config.getWorkspaceId());value.put("embeddingModel",config.getEmbeddingModel());value.put("embeddingRevision",config.getEmbeddingRevision());value.put("dimension",Integer.valueOf(config.getDimension()));value.put("distanceType","COSINE");value.put("snapshotSequence",Long.valueOf(sequence));value.put("snapshotFile",snapshotName);value.put("checksumFile",checksumName);writeAtomic(manifest,json.writeValueAsBytes(value));snapshotSequence=sequence;writeAtomic(directory.resolve("snapshot.bin"),bytes);writeAtomic(directory.resolve("snapshot.sha256"),(sha(bytes)+"\n").getBytes(StandardCharsets.US_ASCII));cleanSnapshots(snapshotName,checksumName);DirectoryStream<Path> stream=Files.newDirectoryStream(walDirectory,"*.wal");try{for(Path file:stream)Files.deleteIfExists(file);}finally{stream.close();}operations=0;}
 private byte[] encodeSnapshot()throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(MAGIC);out.writeInt(FORMAT);out.writeLong(sequence);List<MemoryEntry> ordered=new ArrayList<MemoryEntry>(entries.values());Collections.sort(ordered,new Comparator<MemoryEntry>(){public int compare(MemoryEntry a,MemoryEntry b){return a.getId().compareTo(b.getId());}});out.writeInt(ordered.size());for(MemoryEntry entry:ordered)writeEntry(out,entry);out.flush();return bytes.toByteArray();}
 private void decodeSnapshot(byte[] bytes)throws IOException{DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readInt()!=MAGIC||in.readInt()!=FORMAT) {throw corrupted(); }sequence=in.readLong();int count=in.readInt();if(count<0||count>config.getMaxEntries()) {throw corrupted(); }for(int i=0;i<count;i++){MemoryEntry entry=readEntry(in);validate(entry);if(entries.put(entry.getId(),entry)!=null) {throw corrupted(); }}if(in.read()!=-1) {throw corrupted(); }}
 private byte[] encodeWal(long sequence,byte type,List<MemoryEntry> values,List<String> ids)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(MAGIC);out.writeInt(FORMAT);out.writeLong(sequence);out.writeByte(type);if(type==1){out.writeInt(values.size());for(MemoryEntry entry:values)writeEntry(out,entry);}else{out.writeInt(ids.size());for(String id:ids)writeString(out,id);}out.flush();return bytes.toByteArray();}
 private WalRecord decodeWal(byte[] payload)throws IOException{DataInputStream in=new DataInputStream(new ByteArrayInputStream(payload));if(in.readInt()!=MAGIC||in.readInt()!=FORMAT) {throw corrupted(); }long seq=in.readLong();byte type=in.readByte();int count=in.readInt();if(count<0||count>config.getMaxEntries()||type!=1&&type!=2) {throw corrupted(); }List<MemoryEntry> values=new ArrayList<MemoryEntry>();List<String> ids=new ArrayList<String>();for(int i=0;i<count;i++){if(type==1){MemoryEntry entry=readEntry(in);validate(entry);values.add(entry);}else ids.add(readString(in));}if(in.read()!=-1) {throw corrupted(); }return new WalRecord(seq,type,values,ids);}
 private void apply(WalRecord record){if(record.type==1)for(MemoryEntry entry:record.values)entries.put(entry.getId(),entry);else for(String id:record.ids)entries.remove(id);}
 private void makeCapacity(int additions,Set<String> incoming){int excess=entries.size()+additions-config.getMaxEntries();if(excess<=0)return;if(additions>config.getMaxEntries()||config.getEviction()==SemanticMemoryEviction.REJECT_NEW)limit();List<MemoryEntry> ordered=new ArrayList<MemoryEntry>();for(MemoryEntry entry:entries.values())if(!incoming.contains(entry.getId()))ordered.add(entry);Collections.sort(ordered,new Comparator<MemoryEntry>(){public int compare(MemoryEntry a,MemoryEntry b){int time=Long.compare(a.getCreatedAtEpochMillis(),b.getCreatedAtEpochMillis());return time!=0?time:a.getId().compareTo(b.getId());}});if(ordered.size()<excess)limit();List<String> ids=new ArrayList<String>();for(int i=0;i<excess;i++)ids.add(ordered.get(i).getId());delete(ids);}
 private void purgeExpired(long now){List<String> ids=new ArrayList<String>();for(MemoryEntry entry:entries.values())if(entry.isExpired(now))ids.add(entry.getId());delete(ids);}
 private void delete(List<String> ids){if(ids.isEmpty())return;Collections.sort(ids);append((byte)2,Collections.<MemoryEntry>emptyList(),ids);for(String id:ids)entries.remove(id);checkpointIfNeeded();}
 private void validate(MemoryEntry entry){if(entry.getDimension()!=config.getDimension()||entry.getContent().length()>config.getMaxContentChars())limit();}
 private static void writeEntry(DataOutputStream out,MemoryEntry e)throws IOException{writeString(out,e.getId());writeString(out,e.getTenantId());writeNullable(out,e.getUserId());writeNullable(out,e.getConversationId());writeString(out,e.getDomain());out.writeByte(e.getSourceType().ordinal());writeString(out,e.getSourceId());writeString(out,e.getContent());writeString(out,e.getContentHash());out.writeLong(e.getCreatedAtEpochMillis());out.writeLong(e.getExpiresAtEpochMillis());float[] vector=e.getVector();out.writeInt(vector.length);for(float v:vector)out.writeFloat(v);out.writeInt(e.getMetadata().size());for(Map.Entry<String,String> value:e.getMetadata().entrySet()){writeString(out,value.getKey());writeString(out,value.getValue());}}
 private MemoryEntry readEntry(DataInputStream in)throws IOException{String id=readString(in),tenant=readString(in),user=readNullable(in),conversation=readNullable(in),domain=readString(in);int source=in.readUnsignedByte();if(source>=MemorySourceType.values().length) {throw corrupted(); }String sourceId=readString(in),content=readString(in),hash=readString(in);long created=in.readLong(),expires=in.readLong();int dimension=in.readInt();if(dimension!=config.getDimension())mismatch();float[] vector=new float[dimension];for(int i=0;i<dimension;i++)vector[i]=in.readFloat();int count=in.readInt();if(count<0||count>1000) {throw corrupted(); }Map<String,String> metadata=new LinkedHashMap<String,String>();for(int i=0;i<count;i++){String key=readString(in),value=readString(in);if(metadata.put(key,value)!=null) {throw corrupted(); }}try{return new MemoryEntry(id,tenant,user,conversation,domain,MemorySourceType.values()[source],sourceId,content,hash,vector,created,expires,metadata);}catch(IllegalArgumentException e){throw corrupted();}}
 private static void writeString(DataOutputStream out,String value)throws IOException{byte[] bytes=value.getBytes(StandardCharsets.UTF_8);out.writeInt(bytes.length);out.write(bytes);}private static String readString(DataInputStream in)throws IOException{int length=in.readInt();if(length<0||length>16*1024*1024) {throw corrupted(); }byte[] bytes=new byte[length];in.readFully(bytes);return new String(bytes,StandardCharsets.UTF_8);}private static void writeNullable(DataOutputStream out,String value)throws IOException{out.writeBoolean(value!=null);if(value!=null)writeString(out,value);}private static String readNullable(DataInputStream in)throws IOException{return in.readBoolean()?readString(in):null;}
 private static double cosine(float[] a,float[] b){double dot=0,na=0,nb=0;for(int i=0;i<a.length;i++){dot+=(double)a[i]*b[i];na+=(double)a[i]*a[i];nb+=(double)b[i]*b[i];}return na==0||nb==0?-1:Math.max(-1,Math.min(1,dot/(Math.sqrt(na)*Math.sqrt(nb))));}
 private static void writeAtomic(Path target,byte[] bytes)throws IOException{Path temp=target.resolveSibling(target.getFileName()+".tmp");FileChannel channel=FileChannel.open(temp,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE);try{ByteBuffer buffer=ByteBuffer.wrap(bytes);while(buffer.hasRemaining())channel.write(buffer);channel.force(true);}finally{channel.close();}Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 private Path safeManaged(String name){if(name==null||name.contains("/")||name.contains("\\")||name.contains("..")) {throw corrupted(); }return directory.resolve(name);}
 private void cleanSnapshots(String keepSnapshot,String keepChecksum)throws IOException{DirectoryStream<Path> stream=Files.newDirectoryStream(directory,"snapshot-*.*");try{for(Path file:stream){String name=file.getFileName().toString();if(!name.equals(keepSnapshot)&&!name.equals(keepChecksum))Files.deleteIfExists(file);}}finally{stream.close();}}
 private static byte[] rawSha(byte[] bytes){try{return MessageDigest.getInstance("SHA-256").digest(bytes);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private static String sha(byte[] bytes){StringBuilder value=new StringBuilder(64);for(byte b:rawSha(bytes))value.append(String.format("%02x",b&255));return value.toString();}private static int number(Object value){return value instanceof Number?((Number)value).intValue():-1;}private static long longNumber(Object value){return value instanceof Number?((Number)value).longValue():-1;}private static String text(Object value,String fallback){return value instanceof String?(String)value:fallback;}private static boolean blank(String value){return value==null||value.trim().isEmpty();}private void open(){if(closed) {throw new IllegalStateException("semantic memory store is closed"); }}
 private static void close(FileChannel channel){if(channel!=null)try{channel.close();}catch(IOException ignored){}}private static ClaraException locked(){return SemanticMemoryErrors.error(ErrorCodes.SEMANTIC_MEMORY_LOCKED, ErrorCategory.CONFLICT,true);}private static ClaraException corrupted(){return SemanticMemoryErrors.error(ErrorCodes.SEMANTIC_MEMORY_CORRUPTED,ErrorCategory.INTERNAL,false);}private static void mismatch(){throw SemanticMemoryErrors.error(ErrorCodes.SEMANTIC_MEMORY_CONFIG_MISMATCH,ErrorCategory.CONFIGURATION,false);}private static void limit(){throw SemanticMemoryErrors.error(ErrorCodes.SEMANTIC_MEMORY_RESOURCE_LIMIT,ErrorCategory.RESOURCE_LIMIT,false);}
 /**
  * 表示预写日志的持久化记录。
  */
 private static final class WalRecord{private final long sequence;private final byte type;private final List<MemoryEntry> values;private final List<String> ids;private WalRecord(long sequence,byte type,List<MemoryEntry> values,List<String> ids){this.sequence=sequence;this.type=type;this.values=values;this.ids=ids;}}
}
